{"path": "wordmaster-backend/src/main/java/com/wordmaster/util/RedisUtil.java", "content": "package com.wordmaster.util;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Component;

import java.util.concurrent.TimeUnit;

@Component
public class RedisUtil {

    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    /**
     * 设置缓存
     */
    public void set(String key, Object value) {
        redisTemplate.opsForValue().set(key, value);
    }

    /**
     * 设置缓存并设置过期时间
     */
    public void set(String key, Object value, long timeout, TimeUnit unit) {
        redisTemplate.opsForValue().set(key, value, timeout, unit);
    }

    /**
     * 获取缓存
     */
    public Object get(String key) {
        return redisTemplate.opsForValue().get(key);
    }

    /**
     * 删除缓存
     */
    public Boolean delete(String key) {
        return redisTemplate.delete(key);
    }

    /**
     * 判断缓存是否存在
     */
    public Boolean hasKey(String key) {
        return redisTemplate.hasKey(key);
    }

    /**
     * 设置过期时间
     */
    public Boolean expire(String key, long timeout, TimeUnit unit) {
        return redisTemplate.expire(key, timeout, unit);
    }

    /**
     * 获取过期时间
     */
    public Long getExpire(String key, TimeUnit unit) {
        return redisTemplate.getExpire(key, unit);
    }

    /**
     * 递增
     */
    public Long increment(String key, long delta) {
        return redisTemplate.opsForValue().increment(key, delta);
    }

    /**
     * 递减
     */
    public Long decrement(String key, long delta) {
        return redisTemplate.opsForValue().decrement(key, delta);
    }

    /**
     * 获取用户相关的缓存键
     */
    public String getUserKey(Long userId) {
        return "user:" + userId;
    }

    /**
     * 获取单词相关的缓存键
     */
    public String getWordKey(Long wordId) {
        return "word:" + wordId;
    }

    /**
     * 获取学习记录相关的缓存键
     */
    public String getStudyRecordKey(Long userId, Long wordId) {
        return "study:user:" + userId + ":word:" + wordId;
    }

    /**
     * 获取用户统计相关的缓存键
     */
    public String getUserStatKey(Long userId, String date) {
        return "stat:user:" + userId + ":date:" + date;
    }
}"}

