{"path": "wordmaster-backend/src/main/java/com/wordmaster/util/ForgettingCurveUtil.java", "content": "package com.wordmaster.util;

import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class ForgettingCurveUtil {

    /**
     * 根据掌握程度和复习次数计算下次复习时间间隔（小时）
     * 
     * @param masteryLevel 掌握程度（1-5）
     * @param reviewCount 复习次数
     * @return 下次复习时间间隔（小时）
     */
    public int calculateNextReviewInterval(int masteryLevel, int reviewCount) {
        // 基础间隔（小时）
        int baseInterval;

        switch (masteryLevel) {
            case 1: // 完全不会
                baseInterval = 1;  // 1小时后复习
                break;
            case 2: // 有点印象
                baseInterval = 6;  // 6小时后复习
                break;
            case 3: // 基本掌握
                baseInterval = 24; // 1天后复习
                break;
            case 4: // 熟练掌握
                baseInterval = 72; // 3天后复习
                break;
            case 5: // 完全掌握
